'use client';

import React, { useState, useEffect } from 'react';
import styles from './orders.module.css';
import { INITIAL_ORDERS } from '@/lib/mockData';

export default function AdminOrders() {
    const [orders, setOrders] = useState<any[]>([]);

    useEffect(() => {
        const saved = localStorage.getItem('jk_orders');
        if (saved) {
            setOrders(JSON.parse(saved));
        } else {
            setOrders(INITIAL_ORDERS);
            localStorage.setItem('jk_orders', JSON.stringify(INITIAL_ORDERS));
        }
    }, []);

    const handleStatusChange = (id: string, newStatus: string) => {
        const newOrders = orders.map(o => o._id === id ? { ...o, status: newStatus } : o);
        setOrders(newOrders);
        localStorage.setItem('jk_orders', JSON.stringify(newOrders));
    };

    const handleReset = () => {
        if (confirm('Reset orders history?')) {
            setOrders(INITIAL_ORDERS);
            localStorage.setItem('jk_orders', JSON.stringify(INITIAL_ORDERS));
        }
    };

    return (
        <div className={styles.container}>
            <div className={styles.header}>
                <h1>Manage Orders</h1>
                <button className={styles.resetBtn} onClick={handleReset}>Reset History</button>
            </div>

            <div className={styles.orderTableWrapper}>
                <table className={styles.table}>
                    <thead>
                        <tr>
                            <th>Order ID</th>
                            <th>Date</th>
                            <th>Customer</th>
                            <th>Product</th>
                            <th>Qty</th>
                            <th>Total</th>
                            <th>Status</th>
                        </tr>
                    </thead>
                    <tbody>
                        {orders.map((o) => (
                            <tr key={o._id}>
                                <td><strong>{o.orderId}</strong></td>
                                <td>{new Date(o.createdAt).toLocaleDateString()}</td>
                                <td>
                                    <div className={styles.customerDetail}>
                                        <span className={styles.custName}>{o.customerName}</span>
                                        <span className={styles.custMobile}>{o.mobileNumber}</span>
                                        <span className={styles.custAddr}>{o.address}</span>
                                    </div>
                                </td>
                                <td>{o.product?.name || 'Unknown'}</td>
                                <td>{o.quantity} Kg</td>
                                <td>₹{(o.product?.finalPrice || 0) * o.quantity}</td>
                                <td>
                                    <select
                                        value={o.status}
                                        onChange={(e) => handleStatusChange(o._id, e.target.value)}
                                        className={`${styles.statusSelect} ${styles[o.status.toLowerCase()]}`}
                                    >
                                        <option value="PENDING">Pending</option>
                                        <option value="SHIPPED">Shipped</option>
                                        <option value="DELIVERED">Delivered</option>
                                        <option value="CANCELLED">Cancelled</option>
                                    </select>
                                </td>
                            </tr>
                        ))}
                        {orders.length === 0 && (
                            <tr>
                                <td colSpan={7} style={{ textAlign: 'center', padding: '2rem' }}>No orders found.</td>
                            </tr>
                        )}
                    </tbody>
                </table>
            </div>
        </div>
    );
}
